def halvings(n):
    count = 0
    while n > 1:
        n //= 2
        count += 1
    return count
for n in [0, 1, 7, 8, 16]:
    print(n, halvings(n))

def growth_counts(n):
    fixed = 1
    linear = 0
    pairs = 0
    for i in range(n):
        linear += 1
        for j in range(n):
            pairs += 1
    halvings = 0
    remaining = n
    while remaining > 1:
        remaining //= 2
        halvings += 1
    return fixed, linear, pairs, halvings
for n in [0, 7, 8]:
    print(n, growth_counts(n))

def binary_find(values, target):
    low = 0
    high = len(values) - 1
    probes = 0
    while low <= high:
